'use client';

import React, { useState } from 'react';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  departmentName?: string;
  targetWorkspaceUrl?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  onSuccess?: (user: any) => void;
}

export default function AuthModal({
  isOpen,
  onClose,
  departmentName = 'Entraiot',
  targetWorkspaceUrl = '',
  onSuccess
}: AuthModalProps) {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const endpoint = isLogin ? '/api/auth/login' : '/api/auth/register';
    const payload = isLogin ? { email, password } : { name, email, password };

    try {
      const res = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      const data = await res.json();

      if (!res.ok || !data.success) {
        throw new Error(data.error || 'Authentication failed');
      }

      // Store JWT token & user info in localStorage
      localStorage.setItem('entraiot_token', data.token);
      localStorage.setItem('entraiot_user', JSON.stringify(data.user));

      if (onSuccess) onSuccess(data.user);
      onClose();

      // Redirect to specific workspace if specified
      if (targetWorkspaceUrl) {
        window.location.href = targetWorkspaceUrl;
      }
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      setError(err.message || 'Something went wrong');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={overlayStyle}>
      <div style={modalStyle}>
        <button style={closeButtonStyle} onClick={onClose}>×</button>
        
        <div style={{ textAlign: 'center', marginBottom: '1.5rem' }}>
          <span style={badgeStyle}>{departmentName} Portal</span>
          <h2 style={{ margin: '0.5rem 0 0 0', color: '#111', fontSize: '1.5rem', fontWeight: 700 }}>
            {isLogin ? `Sign In to ${departmentName}` : `Create ${departmentName} Account`}
          </h2>
        </div>

        {error && (
          <div style={errorStyle}>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          {!isLogin && (
            <div>
              <label style={labelStyle}>Full Name</label>
              <input
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="John Doe"
                style={inputStyle}
              />
            </div>
          )}

          <div>
            <label style={labelStyle}>Email Address</label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              style={inputStyle}
            />
          </div>

          <div>
            <label style={labelStyle}>Password</label>
            <input
              type="password"
              required
              minLength={6}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              style={inputStyle}
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            style={{ ...buttonStyle, opacity: loading ? 0.7 : 1 }}
          >
            {loading ? 'Authenticating...' : isLogin ? `Enter ${departmentName} Workspace` : 'Register & Enter'}
          </button>
        </form>

        <div style={{ marginTop: '1.5rem', textAlign: 'center', fontSize: '0.9rem', color: '#666' }}>
          {isLogin ? "Don't have an account? " : "Already have an account? "}
          <button
            type="button"
            onClick={() => { setIsLogin(!isLogin); setError(''); }}
            style={toggleButtonStyle}
          >
            {isLogin ? 'Sign Up' : 'Sign In'}
          </button>
        </div>
      </div>
    </div>
  );
}

// Inline Styles for instant render
const overlayStyle: React.CSSProperties = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'rgba(0, 0, 0, 0.75)',
  backdropFilter: 'blur(8px)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  zIndex: 99999,
};

const modalStyle: React.CSSProperties = {
  backgroundColor: '#ffffff',
  borderRadius: '20px',
  padding: '2.5rem',
  width: '100%',
  maxWidth: '420px',
  boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
  position: 'relative',
  fontFamily: 'system-ui, -apple-system, sans-serif'
};

const closeButtonStyle: React.CSSProperties = {
  position: 'absolute',
  top: '1rem',
  right: '1.25rem',
  border: 'none',
  background: 'none',
  fontSize: '1.75rem',
  cursor: 'pointer',
  color: '#888'
};

const badgeStyle: React.CSSProperties = {
  display: 'inline-block',
  padding: '0.25rem 0.75rem',
  backgroundColor: '#EFF6FF',
  color: '#2563EB',
  fontSize: '0.75rem',
  fontWeight: 700,
  borderRadius: '9999px',
  textTransform: 'uppercase',
  letterSpacing: '0.05em'
};

const labelStyle: React.CSSProperties = {
  display: 'block',
  marginBottom: '0.4rem',
  fontSize: '0.875rem',
  fontWeight: 600,
  color: '#374151'
};

const inputStyle: React.CSSProperties = {
  width: '100%',
  padding: '0.75rem 1rem',
  borderRadius: '8px',
  border: '1px solid #D1D5DB',
  fontSize: '1rem',
  boxSizing: 'border-box',
  outline: 'none'
};

const buttonStyle: React.CSSProperties = {
  width: '100%',
  padding: '0.85rem',
  marginTop: '0.5rem',
  backgroundColor: '#2563EB',
  color: '#ffffff',
  border: 'none',
  borderRadius: '8px',
  fontSize: '1rem',
  fontWeight: 600,
  cursor: 'pointer',
  transition: 'background-color 0.2s'
};

const toggleButtonStyle: React.CSSProperties = {
  background: 'none',
  border: 'none',
  color: '#2563EB',
  fontWeight: 600,
  cursor: 'pointer',
  textDecoration: 'underline'
};

const errorStyle: React.CSSProperties = {
  backgroundColor: '#FEE2E2',
  color: '#DC2626',
  padding: '0.75rem 1rem',
  borderRadius: '8px',
  fontSize: '0.875rem',
  marginBottom: '1rem'
};
