"use client";

import { useEffect, useState, useRef } from "react";
import ScrollCanvas from "@/components/ScrollCanvas";
import AuthModal from "@/components/AuthModal";

export default function Home() {
  const [portfolioFinished, setPortfolioFinished] = useState(true);
  const [authConfig, setAuthConfig] = useState<{
    isOpen: boolean;
    departmentName: string;
    targetWorkspaceUrl: string;
  }>({
    isOpen: false,
    departmentName: '',
    targetWorkspaceUrl: ''
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [currentUser, setCurrentUser] = useState<any>(null);
  const iframeRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    // Check if user is already logged in
    const savedUser = localStorage.getItem("entraiot_user");
    if (savedUser) {
      try {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setCurrentUser(JSON.parse(savedUser));
      } catch (err) {}
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data === "portfolioEnded") {
        setPortfolioFinished(true);
        // Allow scrolling on body once portfolio is done
        document.body.style.overflow = "auto";
      }

      // Handle department login clicks inside the portfolio iframe overlay
      if (event.data && event.data.type === "OPEN_DEPARTMENT_LOGIN") {
        const { departmentName, targetUrl } = event.data;
        setAuthConfig({
          isOpen: true,
          departmentName: departmentName || 'Entraiot',
          targetWorkspaceUrl: targetUrl || ''
        });
      }
    };

    // Listen for department login trigger events
    const handleDepartmentLogin = (e: CustomEvent) => {
      const { departmentName, targetUrl } = e.detail || {};
      setAuthConfig({
        isOpen: true,
        departmentName: departmentName || 'Entraiot',
        targetWorkspaceUrl: targetUrl || ''
      });
    };

    // Ensure scrolling is enabled for Stage 2
    document.body.style.overflow = "auto";
    
    window.addEventListener("message", handleMessage);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    window.addEventListener("open-department-login" as any, handleDepartmentLogin);
    
    return () => {
      window.removeEventListener("message", handleMessage);
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      window.removeEventListener("open-department-login" as any, handleDepartmentLogin);
      document.body.style.overflow = "auto";
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("entraiot_token");
    localStorage.removeItem("entraiot_user");
    setCurrentUser(null);
  };

  return (
    <main className="bg-[#050505] min-h-screen relative">
      {/* Top Header Bar for Profile when logged in */}
      {currentUser && (
        <div className="fixed top-4 right-6 z-[60] flex items-center gap-4">
          <div className="flex items-center gap-3 bg-black/60 backdrop-blur-md px-4 py-2 rounded-full border border-white/20 text-white text-sm">
            <span>👤 {currentUser.name || currentUser.email}</span>
            <button
              onClick={handleLogout}
              className="bg-red-500/80 hover:bg-red-600 px-3 py-1 rounded-full text-xs font-semibold transition cursor-pointer"
            >
              Sign Out
            </button>
          </div>
        </div>
      )}

      {/* Auth Modal Component with Department support */}
      <AuthModal
        isOpen={authConfig.isOpen}
        departmentName={authConfig.departmentName}
        targetWorkspaceUrl={authConfig.targetWorkspaceUrl}
        onClose={() => setAuthConfig(prev => ({ ...prev, isOpen: false }))}
        onSuccess={(user) => setCurrentUser(user)}
      />

      {/* The portfolio iframe overlay */}
      <div 
        className={`fixed inset-0 z-50 transition-opacity duration-1000 ease-in-out ${
          portfolioFinished ? "opacity-0 pointer-events-none" : "opacity-100"
        }`}
      >
        <iframe 
          ref={iframeRef}
          src="/portfolio.html?v=world-begins-v2" 
          className="w-full h-full border-none"
          title="Portfolio Experience"
        />
      </div>

      {/* The Bike Scrollytelling Experience */}
      <ScrollCanvas />

    </main>
  );
}
